installation.script:
#!/bin/bash
# OpenClaw installation script (Pelican / Pterodactyl egg)
# Runs inside the installer container. Writes files to /mnt/server,
# which becomes /home/container at runtime.
#
# Pelican exposes the following at install time (set by Wings):
#   SERVER_IP, SERVER_PORT, SERVER_MEMORY
#   P_SERVER_UUID, P_SERVER_ID, P_SERVER_ALLOCATION_LIMIT
# plus every egg variable declared below. We use those to materialise a
# per-deployment openclaw.json so each customer's gateway boots with the
# right Control UI allowed-origins out of the box (unique subdomain +
# IP + port per server).
set -eo pipefail

export DEBIAN_FRONTEND=noninteractive
apt-get update
apt-get install -y --no-install-recommends \
  curl git ca-certificates python3 make g++ unzip openssl tini

# Install Bun (required by openclaw build scripts). Retry on transient fails.
for attempt in 1 2 3 4 5; do
  if curl --retry 5 --retry-all-errors --retry-delay 2 -fsSL https://bun.sh/install | bash; then
    break
  fi
  [ "$attempt" -eq 5 ] && exit 1
  sleep $((attempt * 2))
done
export PATH="/root/.bun/bin:${PATH}"

corepack enable

OPENCLAW_GIT_URL="${OPENCLAW_GIT_URL:-https://github.com/Cyra-Systems/openclaw.git}"
OPENCLAW_GIT_REF="${OPENCLAW_GIT_REF:-main}"

cd /mnt/server

if [ -d .git ]; then
  echo "==> Updating existing checkout to ${OPENCLAW_GIT_REF}"
  git remote set-url origin "${OPENCLAW_GIT_URL}"
  git fetch --prune origin
  git reset --hard "origin/${OPENCLAW_GIT_REF}" || git reset --hard "${OPENCLAW_GIT_REF}"
else
  echo "==> Cloning ${OPENCLAW_GIT_URL} @ ${OPENCLAW_GIT_REF}"
  git init -q
  git remote add origin "${OPENCLAW_GIT_URL}"
  git fetch --depth=1 origin "${OPENCLAW_GIT_REF}"
  git checkout -q FETCH_HEAD
fi

echo "==> Installing node_modules with pnpm (frozen lockfile)"
NODE_OPTIONS="--max-old-space-size=2048" pnpm install --frozen-lockfile

echo "==> Building A2UI bundle (non-fatal on failure)"
pnpm canvas:a2ui:bundle || {
  echo "    A2UI bundle unavailable on this arch - creating stub"
  mkdir -p src/canvas-host/a2ui
  echo "/* A2UI bundle unavailable in this build */" > src/canvas-host/a2ui/a2ui.bundle.js
  echo "stub" > src/canvas-host/a2ui/.bundle.hash
}

echo "==> Building server bundle"
pnpm build:docker

echo "==> Building UI (non-fatal)"
OPENCLAW_PREFER_PNPM=1 pnpm ui:build || true

echo "==> Pruning dev deps"
CI=true NPM_CONFIG_FROZEN_LOCKFILE=false pnpm prune --prod || true

echo "==> Preparing runtime state directory"
mkdir -p /mnt/server/.openclaw

# ---- Auto-generate gateway token if customer left it blank -------------
if [ -z "${OPENCLAW_GATEWAY_TOKEN:-}" ] && [ ! -s /mnt/server/.openclaw/.env ]; then
  GEN_TOKEN="$(openssl rand -hex 32)"
  {
    echo "# Auto-generated by Pelican egg installer"
    echo "OPENCLAW_GATEWAY_TOKEN=${GEN_TOKEN}"
  } > /mnt/server/.openclaw/.env
  chmod 600 /mnt/server/.openclaw/.env
  echo "    Generated gateway token at ~/.openclaw/.env"
fi

# ---- Materialise per-deployment openclaw.json --------------------------
# Populates gateway.bind/port and gateway.controlUi.allowedOrigins from
# the allocation + subdomain so Control UI works on first boot without
# any manual edit. Safe for reinstalls: preserves unrelated keys and
# merges origins set by the user.
echo "==> Writing per-deployment openclaw.json"
OPENCLAW_PUBLIC_HOSTNAME="${OPENCLAW_PUBLIC_HOSTNAME:-}" \
OPENCLAW_PUBLIC_SCHEME="${OPENCLAW_PUBLIC_SCHEME:-https}" \
OPENCLAW_EXTRA_ALLOWED_ORIGINS="${OPENCLAW_EXTRA_ALLOWED_ORIGINS:-}" \
OPENCLAW_GATEWAY_BIND="${OPENCLAW_GATEWAY_BIND:-lan}" \
SERVER_IP="${SERVER_IP:-}" \
SERVER_PORT="${SERVER_PORT:-18789}" \
P_SERVER_UUID="${P_SERVER_UUID:-}" \
node <<'NODE'
const fs = require('fs');
const path = '/mnt/server/.openclaw/openclaw.json';

const port   = Number(process.env.SERVER_PORT) || 18789;
const ip     = (process.env.SERVER_IP || '').trim();
const host   = (process.env.OPENCLAW_PUBLIC_HOSTNAME || '').trim();
const scheme = ((process.env.OPENCLAW_PUBLIC_SCHEME || 'https').trim().toLowerCase() === 'http') ? 'http' : 'https';
const extras = (process.env.OPENCLAW_EXTRA_ALLOWED_ORIGINS || '')
  .split(',').map(s => s.trim()).filter(Boolean);
const bind   = (process.env.OPENCLAW_GATEWAY_BIND || 'lan').trim();
const uuid   = (process.env.P_SERVER_UUID || '').trim();

const origins = new Set([
  `http://localhost:${port}`,
  `http://127.0.0.1:${port}`,
]);
if (ip) origins.add(`http://${ip}:${port}`);
if (host) {
  // Reverse-proxy terminates TLS on the public scheme + default port.
  origins.add(`${scheme}://${host}`);
  // Direct browser access to the allocation port (bypassing the proxy) also works.
  origins.add(`${scheme}://${host}:${port}`);
  // Permit both schemes for local testing.
  if (scheme === 'https') origins.add(`http://${host}:${port}`);
}
for (const o of extras) origins.add(o);

let cfg = {};
try { cfg = JSON.parse(fs.readFileSync(path, 'utf8')); } catch {}
cfg.gateway = cfg.gateway || {};
cfg.gateway.bind = cfg.gateway.bind || bind;
cfg.gateway.port = port;
cfg.gateway.controlUi = cfg.gateway.controlUi || {};

// Merge: keep any allowedOrigins the user already hand-edited on reinstall.
const existing = Array.isArray(cfg.gateway.controlUi.allowedOrigins)
  ? cfg.gateway.controlUi.allowedOrigins.filter(x => typeof x === 'string' && x.trim())
  : [];
cfg.gateway.controlUi.allowedOrigins = [...new Set([...existing, ...origins])];

// Optional: tag the deployment with its Pelican UUID for observability.
if (uuid) {
  cfg.deploymentId = uuid;
}

fs.mkdirSync('/mnt/server/.openclaw', { recursive: true });
fs.writeFileSync(path, JSON.stringify(cfg, null, 2) + '\n');
try { fs.chmodSync(path, 0o600); } catch {}

console.log('    bind:            ' + cfg.gateway.bind);
console.log('    port:            ' + port);
console.log('    allowedOrigins:');
for (const o of cfg.gateway.controlUi.allowedOrigins) console.log('      - ' + o);
NODE

# Yolks runtime UID/GID.
chown -R 988:988 /mnt/server || true

echo "==> OpenClaw installation complete."
